from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color == bg:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            ys = [p[0] for p in comp]
            xs = [p[1] for p in comp]
            r0, r1, c0, c1 = min(ys), max(ys), min(xs), max(xs)
            area = (r1-r0+1) * (c1-c0+1)
            if len(comp) >= 4 and len(comp) / area >= 0.40:
                boxes.append((color, r0, r1, c0, c1))
    for color, r0, r1, c0, c1 in boxes:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
